-- ================================================================
-- diagnostic_questions_chemistry_biology_seed.sql
--
-- Adds Chemistry (36) and Biology (28) questions to diagnostic_questions,
-- closing the gap found while scoping a combined Physics/Chemistry/
-- Biology diagnostic: at the time this was written, diagnostic_questions
-- held 36 validated Physics questions and ZERO for Chemistry, Biology,
-- or Maths — meaning only Physics diagnostics actually worked end to end,
-- despite all four subjects being selectable in assessment-engine.html's
-- picker. This closes Chemistry and Biology specifically (Maths still
-- has none after this file).
--
-- Shape follows the existing Physics rows exactly: subject, exam_board
-- 'AQA', level 'GCSE', tier 'Higher', 4 topics/subtopics-per-question,
-- 4 questions per topic (assessment-engine.html's shuffleByTopic() caps
-- display at 4 per topic regardless of how many exist, so 4 per topic
-- is the natural minimum that guarantees every topic is actually used).
-- Chemistry uses 9 topics (36 questions) matching Physics's exact shape.
-- Biology uses AQA's real 7 top-level GCSE Biology topics (28 questions)
-- rather than inventing 2 extra topics purely to hit 36 — Biology's
-- curriculum genuinely groups into 7, not 9, and topic list here is
-- taken directly from assets/js/spec-map-aqa.js's Biology.AQA array,
-- not invented.
--
-- specification_ref is 'TO_BE_VERIFIED' throughout, NOT a fabricated
-- clause number, unlike the pre-existing Physics rows (which already
-- contain specific-looking refs like "AQA 5.7.1.1" this file's author
-- has not independently verified and did not want to imitate without
-- checking). This matches the standing discipline already established
-- elsewhere in this repo's Lesson Factory pilots
-- (docs/production/INSPIRE-LESSON-PRODUCTION-BLUEPRINT.md Gate 1: "Any
-- unverified official specification claim must remain TO_BE_VERIFIED").
--
-- Every question is original content, written directly against the
-- GCSE AQA Chemistry/Biology specifications' actual topic names (per
-- spec-map-aqa.js), not adapted from any real past paper or other
-- copyrighted source.
--
-- Run once in the Supabase SQL editor.
-- ================================================================

-- ═══════════════════════════════════════════════════════════
-- CHEMISTRY — 9 topics × 4 questions = 36
-- ═══════════════════════════════════════════════════════════

INSERT INTO diagnostic_questions (subject, exam_board, level, tier, topic, subtopic, specification_ref, difficulty, question_text, option_a, option_b, option_c, option_d, option_e, correct_answer, misconception_a, misconception_b, misconception_c, misconception_d, explanation, mark_scheme_point, source, validated, active) VALUES

-- Topic: Atomic Structure
('Chemistry','AQA','GCSE','Higher','Atomic Structure','Structure of the Atom','TO_BE_VERIFIED',1,
 'What is the overall charge of an atom?',
 'Positive','Negative','Neutral','It depends on the element','Not sure','c',
 'The positive charge of the protons is not fully cancelled — this ignores the equal number of electrons.',
 'The negative charge of the electrons is not fully cancelled — this ignores the equal number of protons.',
 'Correct — the number of protons (positive) always equals the number of electrons (negative) in a neutral atom, so the charges cancel.',
 'The charge of a neutral atom does not depend on which element it is — this is true for every element.',
 'An atom contains equal numbers of protons and electrons. Protons carry a +1 charge and electrons carry a -1 charge, so their charges cancel exactly, giving the whole atom no overall charge.',
 'Number of protons = number of electrons, so charges cancel [1]',
 'ai_drafted', true, true),

('Chemistry','AQA','GCSE','Higher','Atomic Structure','Electronic Structure','TO_BE_VERIFIED',2,
 'An atom of sodium has the electronic structure 2,8,1. Which shell is the outermost (highest energy) shell?',
 'The first shell, containing 2 electrons','The second shell, containing 8 electrons','The third shell, containing 1 electron','All three shells are equally outermost','Not sure','c',
 'The first shell (closest to the nucleus) is filled first and is the innermost, lowest-energy shell, not the outermost.',
 'The second shell is full at 8 electrons but is not the outermost shell here — there is a third shell present.',
 'Correct — electron shells fill from the nucleus outward; the third shell, holding the single outer electron, is the outermost occupied shell.',
 'Shells are not all equivalent — they are filled in order from the nucleus outward, and the outermost occupied one determines reactivity.',
 'Electron shells fill in order starting from the shell closest to the nucleus. For sodium (2,8,1), the first shell holds 2, the second holds 8, and the third (outermost) holds the single remaining electron — this outer electron is why sodium is so reactive.',
 'Third shell is outermost, holds 1 electron [1]',
 'ai_drafted', true, true),

('Chemistry','AQA','GCSE','Higher','Atomic Structure','Isotopes','TO_BE_VERIFIED',3,
 'Chlorine-35 and chlorine-37 are both isotopes of chlorine. What is the same about them, and what is different?',
 'Same number of protons; different number of neutrons','Same number of neutrons; different number of protons','Same number of electrons only; both protons and neutrons differ','Same mass number; different atomic number','Not sure','a',
 'Correct — isotopes of the same element always have the same number of protons (same atomic number) but different numbers of neutrons, which changes the mass number.',
 'It is the number of protons, not neutrons, that stays the same between isotopes of one element — this has it backwards.',
 'The number of protons must also match for both to be chlorine at all, since atomic number defines the element.',
 'Isotopes of the same element share the same atomic number (proton number); it is the mass number that differs between them, not the reverse.',
 'Isotopes are atoms of the same element (same number of protons, so same atomic number) with different numbers of neutrons (so different mass numbers). Chlorine-35 has 18 neutrons; chlorine-37 has 20.',
 'Same protons/atomic number, different neutrons/mass number [1]',
 'ai_drafted', true, true),

('Chemistry','AQA','GCSE','Higher','Atomic Structure','The Periodic Table','TO_BE_VERIFIED',2,
 'Elements in the same group of the periodic table have similar chemical properties. Why?',
 'They have the same number of protons','They have the same number of electron shells','They have the same number of electrons in their outer shell','They have the same relative atomic mass','Not sure','c',
 'Number of protons determines which element it is, not which group it belongs to alongside other elements.',
 'Number of electron shells increases going down a group — elements in a group have different numbers of shells, not the same.',
 'Correct — elements in the same group have the same number of outer-shell electrons, which is what mainly determines how an element reacts.',
 'Relative atomic mass increases going down a group and is not what determines chemical similarity between elements.',
 'The group number of a main-group element tells you how many electrons are in its outer shell. Since chemical reactivity is driven mainly by outer-shell electrons, elements in the same group react in similar ways — for example, all Group 1 elements have 1 outer electron and are all very reactive metals.',
 'Same number of outer-shell electrons drives similar reactivity [1]',
 'ai_drafted', true, true),

-- Topic: Bonding
('Chemistry','AQA','GCSE','Higher','Bonding','Ionic Bonding','TO_BE_VERIFIED',2,
 'When sodium reacts with chlorine to form sodium chloride, what happens to the electrons?',
 'A sodium atom gains an electron from a chlorine atom','A sodium atom loses an electron to a chlorine atom','Sodium and chlorine atoms share a pair of electrons','No electrons move; only protons are exchanged','Not sure','b',
 'This has the electron transfer backwards — sodium loses, it does not gain, an electron in this reaction.',
 'Correct — sodium (1 outer electron) transfers it to chlorine (7 outer electrons, needing 1 more), forming Na+ and Cl- ions held together by ionic bonding.',
 'Sharing electrons describes covalent bonding, not the ionic bonding that occurs between a metal and a non-metal like sodium and chlorine.',
 'Protons are never exchanged in a chemical reaction — only electrons move between atoms; the identity of each element (its proton number) stays fixed.',
 'Sodium has one electron in its outer shell and chlorine has seven. Sodium transfers its outer electron to chlorine, forming a positive sodium ion (Na+) and a negative chloride ion (Cl-). The oppositely charged ions are then held together by strong electrostatic forces of attraction — ionic bonding.',
 'Electron transferred from sodium to chlorine, forming ions [1]',
 'ai_drafted', true, true),

('Chemistry','AQA','GCSE','Higher','Bonding','Covalent Bonding','TO_BE_VERIFIED',2,
 'What is a covalent bond?',
 'The transfer of electrons from one atom to another','A shared pair of electrons between two atoms','The attraction between oppositely charged ions','A delocalised sea of electrons around metal ions','Not sure','b',
 'Electron transfer describes ionic bonding, which occurs between metals and non-metals, not covalent bonding.',
 'Correct — a covalent bond is a shared pair of electrons between two atoms, typically between two non-metals, and it holds the atoms together because both nuclei are attracted to the shared pair.',
 'Attraction between oppositely charged ions describes ionic bonding, not covalent bonding.',
 'A delocalised sea of electrons describes metallic bonding, not covalent bonding.',
 'A covalent bond forms when two atoms (usually both non-metals) each contribute one electron to a shared pair. Both positive nuclei are attracted to this shared, negatively charged pair, holding the atoms together.',
 'Covalent bond = shared pair of electrons [1]',
 'ai_drafted', true, true),

('Chemistry','AQA','GCSE','Higher','Bonding','Metallic Bonding','TO_BE_VERIFIED',3,
 'Metals are good conductors of electricity. What property of metallic bonding explains this?',
 'Metal atoms are arranged in a rigid lattice','Metal ions are held together by strong covalent bonds','Delocalised electrons are free to move throughout the structure','Metal atoms share electrons in fixed pairs','Not sure','c',
 'The rigid lattice arrangement itself explains hardness and structure, but is not what allows charge to flow.',
 'Metallic bonding is not covalent bonding — metals do not form fixed covalent bonds between ions.',
 'Correct — in metallic bonding, outer electrons become delocalised (free to move throughout the whole structure), and this flow of charge carriers is what allows metals to conduct electricity.',
 'Electrons in metallic bonding are delocalised, not held in fixed pairs between specific atoms — that description applies to covalent bonding, not metallic.',
 'In a metal, the outer electrons of each atom become delocalised — free to move throughout the whole giant structure rather than staying with one atom. These mobile electrons can carry electrical charge through the metal, which is why metals conduct electricity (and heat).',
 'Delocalised electrons free to move carry charge [1]',
 'ai_drafted', true, true),

('Chemistry','AQA','GCSE','Higher','Bonding','Giant Covalent Structures','TO_BE_VERIFIED',3,
 'Diamond and graphite are both giant covalent structures made only of carbon, but diamond does not conduct electricity while graphite does. Why?',
 'Diamond has stronger covalent bonds than graphite','Every carbon atom in diamond forms 4 covalent bonds, leaving no free electrons; graphite''s carbons form only 3 bonds each, leaving one delocalised electron per atom','Diamond is a metal and graphite is not','Graphite has ionic bonds between its layers','Not sure','b',
 'Bond strength is not the reason for the difference in conductivity — both are strong covalent structures; the electron arrangement is what differs.',
 'Correct — each carbon in diamond uses all 4 outer electrons in 4 covalent bonds, so there are no free electrons to carry charge. In graphite, each carbon forms only 3 bonds, leaving one delocalised electron per atom, free to move between the layers and conduct electricity.',
 'Neither diamond nor graphite is a metal — both are non-metal giant covalent structures made entirely of carbon.',
 'Graphite''s layers are held together by weak forces between layers, not ionic bonds — the bonding within each layer is covalent.',
 'Diamond: each carbon atom forms 4 covalent bonds to 4 other carbons, using all of its outer electrons — no delocalised electrons remain, so diamond does not conduct. Graphite: each carbon forms only 3 covalent bonds within its layer, leaving one outer electron per atom delocalised and free to move, which lets graphite conduct electricity.',
 'Diamond: 4 bonds, no free electrons. Graphite: 3 bonds, 1 delocalised electron per atom [1]',
 'ai_drafted', true, true),

-- Topic: Quantitative Chemistry
('Chemistry','AQA','GCSE','Higher','Quantitative Chemistry','Relative Formula Mass','TO_BE_VERIFIED',2,
 'What is the relative formula mass (Mr) of carbon dioxide, CO2? (Ar: C = 12, O = 16)',
 '28','32','44','16','Not sure','c',
 'This adds only one oxygen instead of two — CO2 contains two oxygen atoms, not one.',
 'This doubles the oxygen contribution incorrectly — check the calculation: 12 + (16 x 2) = 44, not 32.',
 'Correct — Mr = 12 (one carbon) + 16 + 16 (two oxygens) = 44.',
 'This is the mass of oxygen alone, ignoring the carbon atom entirely.',
 'To find relative formula mass, add up the relative atomic masses of every atom shown in the formula. CO2 has one carbon (Ar = 12) and two oxygens (Ar = 16 each): 12 + 16 + 16 = 44.',
 'Mr = 12 + 16 + 16 = 44 [1]',
 'ai_drafted', true, true),

('Chemistry','AQA','GCSE','Higher','Quantitative Chemistry','Moles','TO_BE_VERIFIED',3,
 'How many moles are in 22 g of carbon dioxide, CO2? (Mr of CO2 = 44)',
 '0.5 mol','2 mol','22 mol','44 mol','Not sure','a',
 'Correct — moles = mass ÷ Mr = 22 ÷ 44 = 0.5 mol.',
 'This inverts the calculation — moles = mass divided by Mr, not Mr divided by mass.',
 'This confuses moles with mass in grams — 22 is the given mass, not the number of moles.',
 'This uses the Mr value itself as the answer, rather than dividing the mass by it.',
 'Moles = mass (g) ÷ Mr. Here, mass = 22 g and Mr(CO2) = 44, so moles = 22 ÷ 44 = 0.5 mol.',
 'moles = mass / Mr = 22/44 = 0.5 [1]',
 'ai_drafted', true, true),

('Chemistry','AQA','GCSE','Higher','Quantitative Chemistry','Limiting Reagents','TO_BE_VERIFIED',4,
 'In a reaction, a student has enough of reactant A to make 0.3 mol of product, but only enough of reactant B to make 0.2 mol of product. What determines the actual amount of product formed?',
 'Reactant A, because there is more of it available','Reactant B, because it runs out first and limits the reaction','The average of the two amounts, 0.25 mol','Whichever reactant is added to the flask first','Not sure','b',
 'Having more of reactant A available does not matter — the reaction stops once the reactant that runs out first (the limiting reagent) is used up.',
 'Correct — the limiting reagent is whichever reactant would produce the smaller amount of product; here that is reactant B, so only 0.2 mol of product can form before B runs out.',
 'Product amount is set by the limiting reagent specifically, not an average of both reactants'' potential yields.',
 'The order reactants are added does not determine the limiting reagent — it is whichever reactant is present in the smaller (relatively) amount that runs out first.',
 'The limiting reagent is the reactant that is completely used up first, stopping the reaction. It is identified by comparing how much product each reactant could theoretically produce — whichever gives the smaller amount is the limiting reagent, and that smaller amount is the actual yield.',
 'Limiting reagent = reactant producing the smaller product amount = 0.2 mol [1]',
 'ai_drafted', true, true),

('Chemistry','AQA','GCSE','Higher','Quantitative Chemistry','Percentage Yield','TO_BE_VERIFIED',2,
 'A reaction has a theoretical yield of 20 g but the student actually obtains 15 g. What is the percentage yield?',
 '75%','25%','133%','5%','Not sure','a',
 'Correct — percentage yield = (actual yield ÷ theoretical yield) x 100 = (15 ÷ 20) x 100 = 75%.',
 'This is 100% minus the answer, not the percentage yield itself.',
 'This inverts the fraction (theoretical ÷ actual instead of actual ÷ theoretical), giving a value over 100% which is not possible for percentage yield.',
 'This is simply the difference between the two masses (20 - 15), not a percentage.',
 'Percentage yield = (actual yield ÷ theoretical yield) x 100. Here that is (15 ÷ 20) x 100 = 75%. Percentage yield can never exceed 100%, since you cannot obtain more product than the maximum theoretically possible.',
 'Percentage yield = (15/20) x 100 = 75% [1]',
 'ai_drafted', true, true),

-- Topic: Chemical Changes
('Chemistry','AQA','GCSE','Higher','Chemical Changes','Reactivity Series','TO_BE_VERIFIED',2,
 'A piece of zinc is placed in copper sulfate solution. What happens, and why?',
 'Nothing happens, because zinc and copper are both metals','Zinc displaces copper, because zinc is more reactive than copper','Copper displaces zinc, because copper is more reactive than zinc','The solution evaporates, releasing sulfur dioxide gas','Not sure','b',
 'A displacement reaction does occur here — zinc is more reactive than copper, so a reaction takes place.',
 'Correct — zinc is higher in the reactivity series than copper, so it displaces copper from copper sulfate solution, forming zinc sulfate and depositing copper metal.',
 'This has the reactivity series backwards — zinc, not copper, is the more reactive metal in this pair.',
 'This is not what happens in a displacement reaction between a metal and a metal salt solution — no gas is released in this reaction.',
 'In a displacement reaction, a more reactive metal will displace a less reactive metal from a solution of its salt. Zinc is more reactive than copper, so zinc atoms give up electrons to become Zn2+ ions in solution, while Cu2+ ions gain electrons and are deposited as solid copper metal: Zn + CuSO4 -> ZnSO4 + Cu.',
 'More reactive metal (zinc) displaces less reactive metal (copper) [1]',
 'ai_drafted', true, true),

('Chemistry','AQA','GCSE','Higher','Chemical Changes','Electrolysis','TO_BE_VERIFIED',3,
 'During the electrolysis of molten lead bromide, at which electrode is lead metal produced, and why?',
 'At the anode (positive electrode), because Pb2+ ions are attracted there','At the cathode (negative electrode), because Pb2+ ions are attracted there and gain electrons','At the anode, because bromide ions are attracted there','Lead is produced at both electrodes equally','Not sure','b',
 'Positive Pb2+ ions are attracted to the negative electrode (cathode), not the positive anode — opposite charges attract.',
 'Correct — Pb2+ ions are positively charged, so they are attracted to the negative cathode, where they gain electrons (are reduced) to form neutral lead atoms.',
 'Bromide ions (Br-) are the ones attracted to the anode, not lead ions — this mixes up which ion goes to which electrode.',
 'The two electrodes produce different products in electrolysis — lead forms only at the cathode, while bromine gas forms at the anode.',
 'In electrolysis of molten lead bromide, the positive lead ions (Pb2+) are attracted to the negative cathode, where they each gain 2 electrons to become neutral lead atoms (reduction). The negative bromide ions (Br-) are attracted to the positive anode, where they lose electrons to form bromine gas (oxidation).',
 'Pb2+ attracted to cathode, gains electrons, forms lead metal [1]',
 'ai_drafted', true, true),

('Chemistry','AQA','GCSE','Higher','Chemical Changes','Acids and Alkalis','TO_BE_VERIFIED',1,
 'A solution has a pH of 3. What does this tell you about the solution?',
 'It is strongly alkaline','It is neutral','It is acidic','It is a pure metal oxide','Not sure','c',
 'A pH of 3 is well below 7, so the solution is acidic, not alkaline — pH values above 7 indicate alkalinity.',
 'A neutral solution has a pH of exactly 7, not 3.',
 'Correct — any pH below 7 indicates an acidic solution; the lower the number, the more strongly acidic it is.',
 'pH describes how acidic or alkaline a solution is, not whether it is a metal oxide — this is a category error.',
 'The pH scale runs from 0 to 14. A pH of 7 is neutral, values below 7 are acidic (the lower the number, the more strongly acidic), and values above 7 are alkaline (the higher the number, the more strongly alkaline).',
 'pH < 7 indicates an acidic solution [1]',
 'ai_drafted', true, true),

('Chemistry','AQA','GCSE','Higher','Chemical Changes','Neutralisation','TO_BE_VERIFIED',2,
 'What are the products when hydrochloric acid reacts with sodium hydroxide?',
 'Sodium chloride and water','Sodium chloride and hydrogen gas','Sodium oxide and water','Sodium chloride, water, and carbon dioxide','Not sure','a',
 'Correct — this is a neutralisation reaction between an acid and an alkali, producing a salt (sodium chloride) and water: HCl + NaOH -> NaCl + H2O.',
 'Hydrogen gas is released when an acid reacts with a reactive metal, not when it reacts with an alkali such as sodium hydroxide.',
 'Sodium oxide is not formed in this reaction — the products of acid + alkali are a salt and water.',
 'Carbon dioxide is released only when an acid reacts with a carbonate, not with an alkali like sodium hydroxide.',
 'When an acid reacts with an alkali (a soluble base), the products are always a salt and water — this is neutralisation. Hydrochloric acid + sodium hydroxide produces the salt sodium chloride, plus water: HCl + NaOH -> NaCl + H2O.',
 'Acid + alkali -> salt + water [1]',
 'ai_drafted', true, true),

-- Topic: Energy Changes
('Chemistry','AQA','GCSE','Higher','Energy Changes','Exothermic and Endothermic','TO_BE_VERIFIED',1,
 'In an exothermic reaction, what happens to the temperature of the surroundings?',
 'It increases, because energy is transferred to the surroundings','It decreases, because energy is taken in from the surroundings','It stays exactly the same','It depends on the state of the reactants','Not sure','a',
 'Correct — an exothermic reaction releases energy to the surroundings, so the surroundings'' temperature rises.',
 'This describes an endothermic reaction, where energy is taken in from the surroundings, causing the temperature to fall — the opposite of exothermic.',
 'The surrounding temperature does change in an exothermic reaction — energy is being transferred out, which is detectable as a temperature rise.',
 'The energy change (exothermic or endothermic) is a property of the reaction itself, not something that varies simply with the physical state of the reactants.',
 'An exothermic reaction transfers energy to the surroundings (often as heat), so the temperature of the surroundings increases. Combustion and neutralisation reactions are common examples of exothermic reactions.',
 'Exothermic: energy released to surroundings, temperature rises [1]',
 'ai_drafted', true, true),

('Chemistry','AQA','GCSE','Higher','Energy Changes','Bond Energies','TO_BE_VERIFIED',3,
 'During a chemical reaction, is energy released or absorbed when new bonds are formed?',
 'Energy is absorbed when bonds form','Energy is released when bonds form','No energy change occurs when bonds form','It depends only on whether the reaction is exothermic overall','Not sure','b',
 'Bond formation releases energy, not absorbs it — breaking bonds is the step that requires energy input.',
 'Correct — forming new bonds releases energy, because the new bonds are more stable (lower energy) than the separated atoms. Breaking bonds, by contrast, requires an input of energy.',
 'A real energy change does occur every time bonds form — this energy released is what makes bond breaking/forming central to explaining exothermic and endothermic reactions.',
 'Bond formation always releases energy, regardless of the reaction''s overall exothermic or endothermic classification — it is the balance between energy absorbed (breaking bonds) and energy released (forming bonds) that determines the overall reaction type.',
 'Breaking bonds always requires an input of energy (endothermic step), while forming bonds always releases energy (exothermic step). Whether the overall reaction is exothermic or endothermic depends on which of these two energy changes is larger.',
 'Bond formation releases energy; bond breaking requires energy [1]',
 'ai_drafted', true, true),

('Chemistry','AQA','GCSE','Higher','Energy Changes','Reaction Profiles','TO_BE_VERIFIED',2,
 'On a reaction profile diagram for an exothermic reaction, how does the energy level of the products compare with the energy level of the reactants?',
 'Products have higher energy than reactants','Products have lower energy than reactants','Products and reactants have exactly the same energy','It cannot be determined from a reaction profile','Not sure','b',
 'This describes an endothermic reaction profile, where products end up at a higher energy level than the reactants — the opposite of exothermic.',
 'Correct — in an exothermic reaction, energy is released overall, so the products end up at a lower energy level than the reactants on the reaction profile.',
 'If reactants and products had equal energy, no energy would be transferred at all, and the reaction would be neither exothermic nor endothermic.',
 'A reaction profile is specifically designed to show the relative energy levels of reactants and products, and the difference between them (the overall energy change) can be read directly from it.',
 'A reaction profile plots energy against the progress of the reaction. For an exothermic reaction, the products sit at a lower energy level than the reactants, because the reaction released energy overall to the surroundings.',
 'Exothermic profile: products lower energy than reactants [1]',
 'ai_drafted', true, true),

('Chemistry','AQA','GCSE','Higher','Energy Changes','Activation Energy','TO_BE_VERIFIED',2,
 'What is meant by the "activation energy" of a reaction?',
 'The total energy released by the reaction','The minimum energy that colliding particles need for a reaction to occur','The energy needed to break all the bonds in the reactants','The energy of the products at the end of the reaction','Not sure','b',
 'Total energy released describes the overall energy change of the reaction, not the activation energy, which is about the energy barrier to starting the reaction.',
 'Correct — activation energy is the minimum energy that particles must have when they collide for a reaction to actually happen; without enough of it, a collision will not result in a reaction.',
 'Activation energy is not necessarily the energy needed to break every bond in the reactants — it is the minimum energy barrier for a successful collision to occur, shown as the "hump" on a reaction profile.',
 'The energy of the products at the end is a separate point on the reaction profile, not the activation energy itself.',
 'Activation energy is the minimum amount of energy that particles need to have when they collide for the collision to result in a reaction. On a reaction profile, it is shown as the height of the "hump" between reactants and products.',
 'Activation energy = minimum energy needed for a successful collision [1]',
 'ai_drafted', true, true),

-- Topic: Rates and Equilibrium
('Chemistry','AQA','GCSE','Higher','Rates and Equilibrium','Collision Theory','TO_BE_VERIFIED',2,
 'According to collision theory, what two conditions must be met for a chemical reaction to occur between two particles?',
 'The particles must be the same size and have the same charge','The particles must collide, and with enough energy (at least the activation energy)','The particles must be in the same physical state','The particles must both be catalysts','Not sure','b',
 'Particle size and charge are not the conditions collision theory describes — collision theory is about whether particles collide, and with how much energy.',
 'Correct — collision theory states that particles must collide, and they must collide with at least the activation energy, for a reaction to actually take place.',
 'Reactants do not need to be in the same physical state for a reaction to occur — many reactions happen between particles in different states, such as a solid reacting with a gas.',
 'A catalyst is a substance that speeds up a reaction without being used up — reacting particles are not catalysts themselves.',
 'Collision theory states that for particles to react, they must first collide with each other, and that collision must have at least enough energy (the activation energy) to break the bonds needed to start the reaction. A collision without enough energy will not lead to a reaction.',
 'Reaction requires: collision + sufficient energy (>= activation energy) [1]',
 'ai_drafted', true, true),

('Chemistry','AQA','GCSE','Higher','Rates and Equilibrium','Factors Affecting Rate','TO_BE_VERIFIED',2,
 'Increasing the temperature of a reaction increases its rate. Why?',
 'Particles become larger and collide more easily','Particles move faster, so they collide more often and with more energy','The activation energy of the reaction decreases','Particles become less concentrated','Not sure','b',
 'Increasing temperature does not change the size of particles — it changes how fast they move.',
 'Correct — at higher temperatures, particles have more kinetic energy, so they move faster. This means they collide more frequently, and a greater proportion of those collisions have at least the activation energy, so more collisions are successful.',
 'Activation energy is a fixed property of a particular reaction — it does not change with temperature. What changes is the proportion of particles with enough energy to overcome it.',
 'Temperature does not directly change concentration — heating a fixed amount of reactant in a fixed volume does not reduce how much of it is present.',
 'Raising the temperature gives particles more kinetic energy, so they move faster. Faster-moving particles collide more often, and more of those collisions have energy greater than or equal to the activation energy, so a greater proportion of collisions are successful — increasing the rate of reaction.',
 'Higher temperature -> faster particles -> more frequent, more energetic collisions [1]',
 'ai_drafted', true, true),

('Chemistry','AQA','GCSE','Higher','Rates and Equilibrium','Reversible Reactions','TO_BE_VERIFIED',3,
 'What is meant by a "reversible reaction"?',
 'A reaction that only happens once and cannot be repeated','A reaction where the products can react together to reform the original reactants','A reaction that requires a catalyst to occur at all','A reaction between two reversible metals','Not sure','b',
 'A reversible reaction can happen repeatedly in both directions — this option describes something being one-off, which is the opposite idea.',
 'Correct — in a reversible reaction, the products of the forward reaction can react with each other to reform the original reactants; the reaction can proceed in both directions.',
 'A reversible reaction does not require a catalyst to occur — reversibility is about the reaction being able to go both forwards and backwards, independent of whether a catalyst is used.',
 '"Reversible metals" is not a real chemistry term — reversibility describes the reaction itself, not a property of specific metals.',
 'In a reversible reaction, the products can react together to reform the original reactants, so the reaction can go in both the forward and backward directions, often shown with a double arrow symbol (⇌).',
 'Reversible reaction: products can reform the original reactants [1]',
 'ai_drafted', true, true),

('Chemistry','AQA','GCSE','Higher','Rates and Equilibrium','Le Chatelier''s Principle','TO_BE_VERIFIED',4,
 'A reversible reaction at equilibrium is exothermic in the forward direction. According to Le Chatelier''s principle, what happens to the position of equilibrium if the temperature is increased?',
 'It shifts towards the products, increasing yield of the forward reaction','It shifts towards the reactants, favouring the backward (endothermic) reaction','It does not move at all, since equilibrium is unaffected by temperature','It shifts completely to products, with no reactants remaining','Not sure','b',
 'This is the effect for an endothermic forward reaction, not an exothermic one — with an exothermic forward reaction, increasing temperature favours the reverse direction instead.',
 'Correct — Le Chatelier''s principle says the equilibrium shifts to oppose the change. Increasing temperature favours the endothermic direction (which absorbs the extra energy); since the forward reaction here is exothermic, the backward (endothermic) reaction is favoured, shifting equilibrium towards the reactants.',
 'Temperature is one of the factors that does shift the position of equilibrium in a reversible reaction — this option incorrectly claims equilibrium is unaffected by it.',
 'Equilibrium shifts to favour one direction more than the other, but the reaction remains reversible — it does not go to 100% completion in either direction.',
 'Le Chatelier''s principle states that if a system at equilibrium is subjected to a change, the position of equilibrium shifts to counteract that change. Increasing temperature favours whichever direction is endothermic (since it absorbs the added energy). Since the forward reaction is exothermic here, the reverse (endothermic) reaction is favoured, shifting equilibrium towards the reactants and reducing yield of product.',
 'Equilibrium shifts to favour the endothermic direction when temperature rises [1]',
 'ai_drafted', true, true),

-- Topic: Organic Chemistry
('Chemistry','AQA','GCSE','Higher','Organic Chemistry','Alkanes','TO_BE_VERIFIED',1,
 'Alkanes are described as "saturated" hydrocarbons. What does "saturated" mean in this context?',
 'They contain only single covalent bonds between carbon atoms','They contain at least one carbon-carbon double bond','They dissolve completely in water','They contain only carbon atoms, no hydrogen','Not sure','a',
 'Correct — "saturated" means the molecule contains only single covalent bonds between carbon atoms, so it holds the maximum possible number of hydrogen atoms.',
 'The presence of a carbon-carbon double bond describes an unsaturated hydrocarbon (an alkene), not a saturated one like an alkane.',
 'Being saturated in chemistry does not refer to solubility in water — this is a different, everyday meaning of the word "saturated."',
 'Alkanes are hydrocarbons, meaning they contain both carbon and hydrogen atoms — a compound with no hydrogen would not be a hydrocarbon at all.',
 'A saturated hydrocarbon contains only single covalent bonds between its carbon atoms, meaning each carbon holds as many hydrogen atoms as possible. Alkanes (such as methane, CH4, and ethane, C2H6) are all saturated hydrocarbons.',
 'Saturated = only single C-C bonds [1]',
 'ai_drafted', true, true),

('Chemistry','AQA','GCSE','Higher','Organic Chemistry','Cracking','TO_BE_VERIFIED',2,
 'Why are long-chain hydrocarbons from crude oil "cracked" into shorter ones?',
 'To make them heavier and more viscous for use as fuel oil','To produce shorter, more useful hydrocarbons, including alkenes for making polymers','To remove all the carbon atoms from the molecule','To convert them directly into crude oil again','Not sure','b',
 'Cracking makes hydrocarbons lighter and less viscous, not heavier — this is the opposite of what cracking achieves.',
 'Correct — cracking breaks long-chain, less useful hydrocarbons into shorter, more useful ones, including smaller alkanes for fuels and alkenes, which are needed as the starting material for making polymers.',
 'Cracking breaks carbon-carbon bonds to produce shorter hydrocarbon molecules — it does not remove carbon atoms from the compound entirely.',
 'Crude oil is the raw material cracking starts from — cracking produces new, more useful products from it, not a route back to crude oil itself.',
 'Cracking is a process that breaks down long-chain hydrocarbons (which are in less demand) into shorter, more useful ones by heating them, sometimes with a catalyst. This produces smaller alkanes, useful as fuels, and alkenes, which are essential as the starting material for making polymers.',
 'Cracking produces shorter, more useful hydrocarbons and alkenes [1]',
 'ai_drafted', true, true),

('Chemistry','AQA','GCSE','Higher','Organic Chemistry','Alkenes','TO_BE_VERIFIED',2,
 'How can you test whether a hydrocarbon is an alkene rather than an alkane, using bromine water?',
 'An alkene will turn bromine water from orange to colourless; an alkane will not','An alkane will turn bromine water from orange to colourless; an alkene will not','Both alkanes and alkenes turn bromine water colourless','Neither alkanes nor alkenes react with bromine water','Not sure','a',
 'Correct — alkenes contain a reactive carbon-carbon double bond, which reacts with bromine water, decolourising it from orange to colourless. Alkanes, being saturated, do not react and the bromine water stays orange.',
 'This has the test result backwards — it is the alkene (unsaturated) that decolourises bromine water, not the alkane (saturated).',
 'Only alkenes decolourise bromine water; alkanes, lacking a reactive double bond, do not react with it and it stays orange.',
 'Alkenes do react with bromine water because of their reactive carbon-carbon double bond — this is exactly what makes the bromine water test useful for distinguishing them from alkanes.',
 'The bromine water test distinguishes alkenes from alkanes: alkenes have a reactive carbon-carbon double bond that reacts with bromine water, turning it from orange to colourless. Alkanes have no such double bond (they are saturated), so bromine water stays orange when mixed with an alkane.',
 'Alkene decolourises bromine water (orange to colourless); alkane does not [1]',
 'ai_drafted', true, true),

('Chemistry','AQA','GCSE','Higher','Organic Chemistry','Polymers','TO_BE_VERIFIED',2,
 'Poly(ethene) is made by joining together many small ethene molecules. What is this process called, and what type of molecules are the small starting units?',
 'Combustion; the small units are called catalysts','Polymerisation; the small units are called monomers','Electrolysis; the small units are called isotopes','Neutralisation; the small units are called alkalis','Not sure','b',
 'Combustion is a burning reaction, not the process of joining small molecules into a long chain.',
 'Correct — this process is called polymerisation, and the small molecules that join together to form the long-chain polymer are called monomers. In this case, many ethene monomers join to form the polymer poly(ethene).',
 'Electrolysis uses electricity to break down a compound — it is unrelated to joining small organic molecules into long polymer chains.',
 'Neutralisation is the reaction between an acid and a base — this is a completely different type of reaction from polymer formation.',
 'Polymerisation is the process by which many small molecules called monomers join together (usually via addition reactions across double bonds) to form one very long molecule called a polymer. Poly(ethene) is formed from many ethene (CH2=CH2) monomers joining together.',
 'Polymerisation joins monomers into a polymer [1]',
 'ai_drafted', true, true),

-- Topic: Chemical Analysis
('Chemistry','AQA','GCSE','Higher','Chemical Analysis','Chromatography','TO_BE_VERIFIED',3,
 'In paper chromatography, a substance with a higher Rf value travels further up the paper than a substance with a lower Rf value. Why?',
 'It is more strongly attracted to the stationary phase (the paper)','It is more soluble in the mobile phase (the solvent) relative to the stationary phase','It has a larger relative formula mass','It is a purer sample than the other substance','Not sure','b',
 'Being more strongly attracted to the stationary phase would make a substance travel less far, not more — this is the opposite of what a high Rf value indicates.',
 'Correct — a substance that is more soluble in the solvent (mobile phase) relative to how strongly it sticks to the paper (stationary phase) spends more time moving with the solvent, so it travels further, giving a higher Rf value.',
 'Rf value is about how the substance distributes between the two phases (solvent and paper), not directly about its relative formula mass.',
 'Rf value tells you about a substance''s identity (by comparison to known values), not about how pure a sample is — chromatography can show purity by whether one spot or several spots appear, not by the Rf value of a single spot.',
 'In chromatography, each substance distributes between the mobile phase (solvent, moving up the paper) and the stationary phase (the paper itself). A substance that is more soluble in the solvent relative to how strongly it binds to the paper spends more time being carried along by the solvent, travelling further up the paper and giving a higher Rf value (Rf = distance moved by substance ÷ distance moved by solvent).',
 'Higher Rf = more soluble in mobile phase relative to stationary phase [1]',
 'ai_drafted', true, true),

('Chemistry','AQA','GCSE','Higher','Chemical Analysis','Flame Tests','TO_BE_VERIFIED',1,
 'A student performs a flame test on an unknown metal compound and observes a lilac flame. Which metal ion is likely present?',
 'Sodium (Na+)','Potassium (K+)','Calcium (Ca2+)','Copper (Cu2+)','Not sure','b',
 'Sodium ions produce a persistent orange/yellow flame in a flame test, not lilac.',
 'Correct — potassium ions (K+) characteristically produce a lilac flame in a flame test.',
 'Calcium ions produce a brick-red/orange flame in a flame test, not lilac.',
 'Copper ions produce a blue-green flame in a flame test, not lilac.',
 'Different metal ions produce characteristic flame colours when heated, which can be used to identify them: lithium is red, sodium is orange/yellow, potassium is lilac, calcium is brick-red/orange, and copper is blue-green.',
 'Lilac flame indicates potassium ions [1]',
 'ai_drafted', true, true),

('Chemistry','AQA','GCSE','Higher','Chemical Analysis','Tests for Gases','TO_BE_VERIFIED',1,
 'How do you test for the presence of carbon dioxide gas?',
 'Hold a lit splint to the gas — a squeaky pop confirms carbon dioxide','Bubble the gas through limewater — it turns cloudy/milky if carbon dioxide is present','Hold a glowing splint in the gas — it relights if carbon dioxide is present','Test the gas with damp litmus paper — it turns red if carbon dioxide is present','Not sure','b',
 'A "squeaky pop" with a lit splint is the test for hydrogen gas, not carbon dioxide.',
 'Correct — bubbling a gas through limewater and observing it turn cloudy (milky) is the standard test for carbon dioxide.',
 'A glowing splint relighting is the test for oxygen gas, not carbon dioxide.',
 'Damp litmus paper turning red (and bleaching white) is associated with testing for chlorine gas, not carbon dioxide.',
 'The standard test for carbon dioxide gas is to bubble it through limewater (a solution of calcium hydroxide). If carbon dioxide is present, the limewater turns cloudy/milky, because it reacts to form insoluble calcium carbonate.',
 'CO2 turns limewater cloudy [1]',
 'ai_drafted', true, true),

('Chemistry','AQA','GCSE','Higher','Chemical Analysis','Tests for Ions','TO_BE_VERIFIED',3,
 'A student adds a few drops of sodium hydroxide solution to a solution of an unknown metal ion, and a blue precipitate forms. Which metal ion is most likely present?',
 'Calcium (Ca2+)','Copper (Cu2+)','Sodium (Na+)','Iron(III) (Fe3+)','Not sure','b',
 'Calcium ions form a white precipitate with sodium hydroxide, not a blue one.',
 'Correct — copper(II) ions (Cu2+) form a characteristic blue precipitate of copper hydroxide when sodium hydroxide solution is added.',
 'Sodium compounds are soluble and sodium ions do not form a precipitate with sodium hydroxide at all — a flame test, not this precipitate test, is used to identify sodium.',
 'Iron(III) ions form an orange/brown precipitate with sodium hydroxide, not a blue one.',
 'Adding sodium hydroxide solution to a solution containing certain metal ions produces an insoluble metal hydroxide precipitate with a colour characteristic of that metal ion. Copper(II) ions specifically give a blue precipitate; iron(III) gives orange/brown; calcium and magnesium both give white precipitates (magnesium and calcium can then be told apart using other tests, since sodium hydroxide alone gives the same white result for both).',
 'Blue precipitate with NaOH indicates Cu2+ ions [1]',
 'ai_drafted', true, true),

-- Topic: Chemistry of the Atmosphere
('Chemistry','AQA','GCSE','Higher','Chemistry of the Atmosphere','Composition of the Atmosphere','TO_BE_VERIFIED',1,
 'What is the approximate percentage of nitrogen in the Earth''s current atmosphere?',
 'About 21%','About 78%','About 0.04%','About 50%','Not sure','b',
 'About 21% is approximately the percentage of oxygen in the atmosphere, not nitrogen.',
 'Correct — the Earth''s current atmosphere is approximately 78% nitrogen, making it the most abundant gas present.',
 'About 0.04% is approximately the percentage of carbon dioxide in the atmosphere, not nitrogen.',
 'Nitrogen makes up roughly four-fifths (78%) of the atmosphere, considerably more than half.',
 'The Earth''s atmosphere today is approximately 78% nitrogen, 21% oxygen, with the remaining roughly 1% made up of other gases including argon and small amounts of carbon dioxide (about 0.04%).',
 'Nitrogen makes up approximately 78% of the atmosphere [1]',
 'ai_drafted', true, true),

('Chemistry','AQA','GCSE','Higher','Chemistry of the Atmosphere','Greenhouse Gases','TO_BE_VERIFIED',2,
 'Which of the following is a greenhouse gas that contributes to the enhanced greenhouse effect?',
 'Nitrogen','Oxygen','Carbon dioxide','Argon','Not sure','c',
 'Nitrogen, despite being the most abundant atmospheric gas, is not a significant greenhouse gas.',
 'Oxygen is essential for respiration and combustion but is not classified as a significant greenhouse gas.',
 'Correct — carbon dioxide is a key greenhouse gas; it absorbs and re-radiates infrared radiation from the Earth''s surface, and rising levels from human activity are linked to the enhanced greenhouse effect.',
 'Argon is a chemically unreactive noble gas present in small amounts in the atmosphere, and is not a significant greenhouse gas.',
 'Greenhouse gases (including carbon dioxide, methane, and water vapour) absorb infrared radiation reflected from the Earth''s surface and re-radiate some of it back down, warming the atmosphere. Human activities such as burning fossil fuels have increased carbon dioxide levels, contributing to an enhanced greenhouse effect and climate change.',
 'CO2 is a significant greenhouse gas [1]',
 'ai_drafted', true, true),

('Chemistry','AQA','GCSE','Higher','Chemistry of the Atmosphere','Carbon Footprint','TO_BE_VERIFIED',2,
 'What is meant by the "carbon footprint" of a product or activity?',
 'The mass of carbon it physically contains','The total amount of carbon dioxide and other greenhouse gases released over its full life cycle','The number of carbon atoms in its chemical formula','The distance it travels during manufacture, measured in kilometres','Not sure','b',
 'A product''s physical carbon content is a different (and usually much smaller) figure from its carbon footprint, which is about emissions caused, not atoms contained.',
 'Correct — carbon footprint is the total amount of carbon dioxide and other greenhouse gases released over the full life cycle of a product or activity, including production, use, and disposal.',
 'The number of carbon atoms in a chemical formula describes the substance''s composition, not the emissions caused by producing or using it.',
 'Carbon footprint accounts for total greenhouse gas emissions across a product''s whole life cycle, not simply the distance it travels during manufacture (though transport can contribute to it).',
 'A carbon footprint is a measure of the total greenhouse gas emissions (usually expressed as an equivalent mass of carbon dioxide) caused directly and indirectly by an activity or over the life cycle of a product, from production through to disposal.',
 'Carbon footprint = total greenhouse gas emissions over a product''s/activity''s life cycle [1]',
 'ai_drafted', true, true),

('Chemistry','AQA','GCSE','Higher','Chemistry of the Atmosphere','Atmospheric Pollutants','TO_BE_VERIFIED',3,
 'Burning fossil fuels containing sulfur impurities releases sulfur dioxide, which contributes to acid rain. What other common atmospheric pollutant forms when fuels burn at high temperatures in engines, from nitrogen and oxygen in the air itself, rather than from an impurity in the fuel?',
 'Carbon monoxide','Particulates (soot)','Oxides of nitrogen','Unburned hydrocarbons','Not sure','c',
 'Carbon monoxide forms from incomplete combustion of the fuel''s carbon content, not from nitrogen and oxygen in the air reacting together.',
 'Particulates (soot) are unburned carbon particles from incomplete combustion of the fuel itself, not a product of nitrogen and oxygen in the air reacting.',
 'Correct — at the high temperatures inside an engine, nitrogen and oxygen from the air react together to form oxides of nitrogen, which contribute to acid rain and photochemical smog.',
 'Unburned hydrocarbons are fuel that has passed through the engine without combusting fully — they come from the fuel itself, not from nitrogen and oxygen in the air.',
 'At the high temperatures reached inside an engine, nitrogen and oxygen from the air (rather than from the fuel) react together to form oxides of nitrogen (NOx). These contribute to acid rain and can react in sunlight to form photochemical smog, causing respiratory problems.',
 'High engine temperatures cause N2 + O2 in air to react, forming oxides of nitrogen [1]',
 'ai_drafted', true, true);


