INSERT INTO diagnostic_questions (subject, exam_board, level, tier, topic, subtopic, specification_ref, difficulty, question_text, option_a, option_b, option_c, option_d, option_e, correct_answer, misconception_a, misconception_b, misconception_c, misconception_d, explanation, mark_scheme_point, source, validated, active) VALUES

-- Topic: Cell Biology
('Biology','AQA','GCSE','Higher','Cell Biology','Eukaryotic and Prokaryotic Cells','TO_BE_VERIFIED',1,
 'Which of the following is true of a prokaryotic cell, such as a bacterium, but not of a eukaryotic cell?',
 'It has a cell membrane','It contains genetic material','It has no nucleus — its DNA lies free in the cytoplasm','It is always larger than a eukaryotic cell','Not sure','c',
 'Both prokaryotic and eukaryotic cells have a cell membrane — this is not a distinguishing feature between them.',
 'Both prokaryotic and eukaryotic cells contain genetic material — this is not a distinguishing feature between them.',
 'Correct — prokaryotic cells, such as bacteria, have no nucleus; their DNA is a single loop lying free in the cytoplasm, unlike eukaryotic cells, where DNA is enclosed in a nucleus.',
 'Prokaryotic cells are typically much smaller than eukaryotic cells, not larger — this has the size comparison backwards.',
 'The key distinguishing feature is the nucleus: eukaryotic cells (such as animal and plant cells) have their genetic material enclosed within a nucleus, while prokaryotic cells (such as bacteria) have no nucleus — their DNA is a single loop of DNA free in the cytoplasm, sometimes with additional small rings called plasmids.',
 'Prokaryotic cells have no nucleus; DNA is free in the cytoplasm [1]',
 'ai_drafted', true, true),

('Biology','AQA','GCSE','Higher','Cell Biology','Cell Specialisation','TO_BE_VERIFIED',2,
 'A sperm cell has a long tail (flagellum) and many mitochondria. How do these features relate to its function?',
 'The tail is for photosynthesis and mitochondria store genetic information','The tail allows swimming towards the egg, and the many mitochondria provide the energy needed for this movement','The tail and mitochondria have no connection to the sperm cell''s function','The tail is used to absorb nutrients, and mitochondria control cell division','Not sure','b',
 'Sperm cells do not photosynthesise, and mitochondria are the site of respiration, not storage of genetic information.',
 'Correct — the tail allows the sperm cell to swim towards the egg cell, and the large number of mitochondria provide the energy (via aerobic respiration) needed to power this swimming movement.',
 'These features are specific adaptations that directly support the sperm cell''s function of reaching and fertilising an egg — they are not unrelated to what the cell does.',
 'The tail is for movement (swimming), not nutrient absorption, and mitochondria are the site of respiration for energy release, not control of cell division.',
 'A sperm cell is specialised for its function of fertilising an egg cell. Its long tail (flagellum) allows it to swim through fluid to reach the egg, and it contains a large number of mitochondria, which carry out aerobic respiration to release the energy needed to power this swimming movement.',
 'Tail enables swimming; many mitochondria provide energy for movement [1]',
 'ai_drafted', true, true),

('Biology','AQA','GCSE','Higher','Cell Biology','Diffusion, Osmosis and Active Transport','TO_BE_VERIFIED',3,
 'A plant cell is placed in a solution with a lower water concentration than the cell itself (i.e., a more concentrated solution). What is likely to happen to the cell, and by what process?',
 'Water moves into the cell by osmosis, and the cell swells','Water moves out of the cell by osmosis, and the cell becomes flaccid/plasmolysed','Water moves out of the cell by active transport, using energy','Glucose moves into the cell by diffusion','Not sure','b',
 'Water moves out of, not into, a cell placed in a more concentrated external solution — this describes the opposite direction of net water movement.',
 'Correct — water moves by osmosis from a region of higher water concentration (inside the cell) to a region of lower water concentration (the surrounding solution). This causes the cell to lose water, becoming flaccid, and in extreme cases the cell membrane pulls away from the cell wall (plasmolysis).',
 'Osmosis is the movement of water across a partially permeable membrane down a concentration gradient — it does not require energy input, unlike active transport.',
 'The question concerns the movement of water, driven by a concentration difference, which is osmosis — not the diffusion of a dissolved substance like glucose.',
 'Osmosis is the movement of water molecules from a region of higher water concentration to a region of lower water concentration, through a partially permeable membrane, without requiring energy. If the solution surrounding a plant cell has a lower water concentration than the cell''s contents, water moves out of the cell by osmosis, causing the cell to become flaccid and, if enough water is lost, plasmolysed.',
 'Water moves out of cell by osmosis; cell becomes flaccid/plasmolysed [1]',
 'ai_drafted', true, true),

('Biology','AQA','GCSE','Higher','Cell Biology','Mitosis','TO_BE_VERIFIED',2,
 'What is the purpose of mitosis in a multicellular organism?',
 'To produce four genetically different daughter cells for sexual reproduction','To produce two genetically identical daughter cells, for growth and repair of tissues','To halve the number of chromosomes for the production of gametes','To combine genetic material from two parent cells','Not sure','b',
 'Four genetically different daughter cells are produced by meiosis, for sexual reproduction — this describes meiosis, not mitosis.',
 'Correct — mitosis produces two genetically identical daughter cells from one parent cell, and is used by the body for growth and to replace damaged or worn-out cells.',
 'Halving the chromosome number for gamete production describes meiosis, not mitosis — mitosis keeps the chromosome number the same in daughter cells.',
 'Combining genetic material from two parent cells happens during fertilisation, not during mitosis, which involves only one parent cell dividing.',
 'Mitosis is a type of cell division that produces two new cells, each genetically identical to the parent cell and to each other, with the same number of chromosomes. It is used for growth of the organism, and to replace cells that are damaged or have worn out.',
 'Mitosis produces two genetically identical cells, for growth and repair [1]',
 'ai_drafted', true, true),

-- Topic: Organisation
('Biology','AQA','GCSE','Higher','Organisation','Enzymes','TO_BE_VERIFIED',2,
 'Why does an enzyme stop working (denature) if the temperature becomes too high?',
 'The enzyme freezes solid and can no longer move','The active site changes shape, so the substrate can no longer bind to it','The enzyme turns into a different type of molecule entirely','High temperature destroys the substrate but not the enzyme','Not sure','b',
 'Enzymes are proteins and do not freeze at high temperatures — the problem at high temperature is the opposite: too much energy disrupts the enzyme''s structure.',
 'Correct — at high temperatures, the bonds holding the enzyme''s 3D structure together break, changing the shape of its active site. Once the active site no longer fits the substrate, the enzyme can no longer catalyse the reaction, and is said to be denatured.',
 'Denaturing changes the shape of the enzyme''s protein structure, but it is still fundamentally a protein — it does not become an entirely different type of molecule.',
 'It is specifically the enzyme''s own structure — particularly its active site — that is affected by high temperature; this is what stops the reaction, not damage limited to the substrate alone.',
 'Enzymes are proteins with a specific 3D shape, including an active site that fits a particular substrate. At high temperatures, the bonds maintaining this 3D structure break, permanently changing the shape of the active site. Once the substrate no longer fits, the enzyme can no longer catalyse the reaction — this is called denaturing.',
 'High temperature changes active site shape, denaturing the enzyme [1]',
 'ai_drafted', true, true),

('Biology','AQA','GCSE','Higher','Organisation','The Digestive System','TO_BE_VERIFIED',1,
 'Which organ produces bile, which helps digest fats?',
 'The stomach','The liver','The pancreas','The small intestine','Not sure','b',
 'The stomach produces acid and protein-digesting enzymes, but it does not produce bile.',
 'Correct — bile is produced by the liver, then stored in the gallbladder before being released into the small intestine, where it helps digest fats by breaking large fat droplets into smaller ones (emulsification).',
 'The pancreas produces several digestive enzymes and releases them into the small intestine, but it does not produce bile — that is the liver''s role.',
 'The small intestine is where bile acts and where most digestion and absorption occurs, but bile itself is produced in the liver, not the small intestine.',
 'Bile is produced by the liver and stored in the gallbladder. It is released into the small intestine, where it neutralises stomach acid and emulsifies fats — breaking large fat droplets into smaller ones, which increases the surface area for lipase enzymes to digest the fat more efficiently.',
 'Bile is produced by the liver [1]',
 'ai_drafted', true, true),

('Biology','AQA','GCSE','Higher','Organisation','The Heart and Blood Vessels','TO_BE_VERIFIED',3,
 'Why do arteries have thick, muscular walls, while veins have thinner walls but contain valves?',
 'Arteries carry blood at high pressure away from the heart; veins carry blood at lower pressure back to the heart and need valves to prevent backflow','Arteries carry blood back to the heart, so need to be strong; veins carry blood away from the heart at low pressure','Both carry blood at the same pressure, so the wall differences are not functionally important','Veins need thick walls because they carry more blood overall than arteries','Not sure','a',
 'Correct — arteries carry blood away from the heart at high pressure, so need thick, muscular, elastic walls to withstand this pressure. Veins carry blood back to the heart at much lower pressure, so have thinner walls, and contain valves to prevent blood flowing backwards, since there is little pressure to keep it moving forward.',
 'This describes arteries and veins the wrong way round — arteries carry blood away from the heart, and veins carry blood back towards it.',
 'The wall structure differences directly relate to the very different blood pressures in arteries versus veins — this is functionally important, not incidental.',
 'Blood volume carried is not the reason veins have valves — it is because they carry blood at low pressure, so valves are needed to prevent blood flowing backwards.',
 'Arteries carry blood away from the heart at high pressure, so they have thick, muscular, and elastic walls to withstand and help maintain this pressure. Veins carry blood back to the heart at much lower pressure, so their walls are thinner; they also contain valves to prevent blood flowing backwards, since there is little pressure pushing the blood along.',
 'Arteries: thick walls for high pressure. Veins: valves prevent backflow at low pressure [1]',
 'ai_drafted', true, true),

('Biology','AQA','GCSE','Higher','Organisation','Plant Tissues','TO_BE_VERIFIED',2,
 'What are the roles of xylem and phloem tissue in a plant?',
 'Xylem transports water and minerals upward from the roots; phloem transports dissolved sugars (produced by photosynthesis) around the plant','Xylem transports sugars around the plant; phloem transports water and minerals from the roots','Both xylem and phloem transport only water, in opposite directions','Xylem and phloem are both involved only in photosynthesis, not transport','Not sure','a',
 'Correct — xylem tissue transports water and dissolved mineral ions from the roots upward through the plant, in one direction only. Phloem tissue transports dissolved sugars (produced by photosynthesis) from the leaves to other parts of the plant, in both directions, in a process called translocation.',
 'This swaps the roles of xylem and phloem — xylem carries water and minerals, while phloem carries dissolved sugars, not the other way around.',
 'Xylem and phloem carry different substances (water/minerals versus dissolved sugars) — they are not both simply carrying water.',
 'Xylem and phloem are transport tissues, not sites of photosynthesis themselves — photosynthesis occurs mainly in the leaf''s mesophyll cells, and its products are then transported by the phloem.',
 'Xylem tissue is made of dead, hollow cells that transport water and dissolved mineral ions from the roots upward through the plant, in one direction. Phloem tissue is made of living cells that transport dissolved sugars produced by photosynthesis from the leaves to other parts of the plant (such as roots and growing tissue) in a process called translocation, which can occur in either direction.',
 'Xylem: water/minerals up from roots. Phloem: sugars from leaves, both directions [1]',
 'ai_drafted', true, true),

-- Topic: Infection and Response
('Biology','AQA','GCSE','Higher','Infection and Response','Pathogens','TO_BE_VERIFIED',1,
 'Which of these is a type of pathogen that can cause disease?',
 'A red blood cell','A virus','An enzyme','A hormone','Not sure','b',
 'A red blood cell is a normal part of the human body, not a pathogen — it does not cause disease.',
 'Correct — a virus is a type of pathogen: a microorganism that can cause infectious disease, alongside bacteria, fungi, and protists.',
 'An enzyme is a biological catalyst produced by cells, not a disease-causing organism.',
 'A hormone is a chemical messenger produced by the body, not a disease-causing organism.',
 'Pathogens are microorganisms that cause infectious disease. The four main types studied at GCSE are bacteria, viruses, fungi, and protists. A virus is a pathogen that can only reproduce inside living host cells, often damaging them in the process.',
 'A virus is a type of pathogen [1]',
 'ai_drafted', true, true),

('Biology','AQA','GCSE','Higher','Infection and Response','Vaccination','TO_BE_VERIFIED',3,
 'How does vaccination protect a person against a specific disease?',
 'It introduces antibiotics directly into the bloodstream to kill any future pathogens','It introduces a small, safe amount of dead or inactive pathogen, causing white blood cells to produce antibodies and "remember" that pathogen','It removes the person''s ability to catch any disease at all','It directly destroys the pathogen''s DNA before infection can occur','Not sure','b',
 'Vaccines do not contain antibiotics — antibiotics only work against bacteria, and vaccination works differently, by training the immune system itself.',
 'Correct — a vaccine contains a small, safe amount of a dead or inactive form of a pathogen (or parts of it). This causes white blood cells to produce antibodies specific to that pathogen and creates memory cells, so if the real pathogen is encountered later, the immune system can respond much more quickly, often before the person becomes ill.',
 'Vaccination protects against the specific disease the vaccine targets, not against all diseases in general.',
 'Vaccination works by stimulating the person''s own immune system to produce antibodies, not by directly destroying the pathogen''s DNA.',
 'A vaccine contains a small, safe amount of a dead or inactivated pathogen (or a harmless part of it). This stimulates white blood cells to produce antibodies against that specific pathogen, and creates long-lasting memory cells. If the person is later exposed to the real, live pathogen, their immune system recognises it and can produce antibodies rapidly, usually preventing illness.',
 'Vaccine stimulates antibody production and memory cells for a specific pathogen [1]',
 'ai_drafted', true, true),

('Biology','AQA','GCSE','Higher','Infection and Response','Antibiotics','TO_BE_VERIFIED',2,
 'Why are antibiotics effective against bacterial infections but not against viral infections such as the common cold?',
 'Antibiotics target processes specific to bacterial cells, which viruses do not have, since viruses are not living cells','Viruses are much larger than bacteria, so antibiotics cannot physically reach them','Antibiotics only work on infections in the digestive system','Bacteria are always harmless, so treating them is unnecessary','Not sure','a',
 'Correct — antibiotics work by targeting specific structures or processes found in bacterial cells (such as their cell walls) that human and viral particles do not have. Viruses are not living cells and reproduce inside a host''s own cells using the host''s machinery, so there is no equivalent bacterial-specific target for antibiotics to act on.',
 'This is not about size or physical reach — antibiotics are ineffective against viruses because viruses lack the specific cellular structures and processes that antibiotics are designed to disrupt.',
 'Antibiotics can treat bacterial infections throughout the body, not only in the digestive system — the reason they don''t work on viruses is about the biological target, not the location of infection.',
 'Bacteria are not always harmless — many bacterial species cause serious disease, which is exactly why antibiotics were developed to treat bacterial infections.',
 'Antibiotics work by disrupting processes specific to bacterial cells, such as bacterial cell wall construction, which are different from human cell processes. Viruses are not cells at all — they reproduce by inserting their genetic material into a host''s own cells and hijacking the host''s machinery — so there is no equivalent bacterial target for antibiotics to act on, which is why antibiotics are ineffective against viral infections.',
 'Antibiotics target bacteria-specific processes; viruses lack these targets [1]',
 'ai_drafted', true, true),

('Biology','AQA','GCSE','Higher','Infection and Response','Spread of Disease','TO_BE_VERIFIED',2,
 'Which of the following is a way that many respiratory pathogens, such as the flu virus, commonly spread between people?',
 'Direct transfer of genetic material through soil','Droplet infection — through coughing or sneezing, releasing pathogen-containing droplets into the air','Only through direct contact with an infected person''s blood','They cannot spread between people at all','Not sure','b',
 'Soil-based genetic transfer is not a recognised route by which respiratory pathogens like flu spread between people.',
 'Correct — many respiratory pathogens spread by droplet infection: when an infected person coughs or sneezes, tiny droplets containing the pathogen are released into the air and can be inhaled by others nearby.',
 'While bloodborne transmission is a real route for some pathogens (such as certain viruses), it is not the typical way respiratory pathogens like flu spread — droplet infection through the air is far more common for these.',
 'Respiratory pathogens like the flu virus clearly do spread between people, which is why outbreaks and epidemics of flu occur regularly.',
 'Many pathogens, particularly those causing respiratory illnesses like flu and colds, spread by droplet infection. When an infected person coughs, sneezes, or even talks, tiny droplets of saliva or mucus containing the pathogen are released into the air, and can be breathed in by other people nearby, or land on surfaces that are then touched.',
 'Droplet infection spreads pathogens through coughing/sneezing [1]',
 'ai_drafted', true, true),

-- Topic: Bioenergetics
('Biology','AQA','GCSE','Higher','Bioenergetics','Photosynthesis','TO_BE_VERIFIED',1,
 'What are the raw materials needed for photosynthesis, and what are the products?',
 'Raw materials: glucose and oxygen. Products: carbon dioxide and water','Raw materials: carbon dioxide and water. Products: glucose and oxygen','Raw materials: carbon dioxide and oxygen. Products: glucose and water','Raw materials: nitrogen and water. Products: glucose and carbon dioxide','Not sure','b',
 'This has photosynthesis''s raw materials and products swapped — glucose and oxygen are the products, not the raw materials.',
 'Correct — photosynthesis takes in carbon dioxide and water (using light energy) and produces glucose and oxygen: 6CO2 + 6H2O -> C6H12O6 + 6O2.',
 'Oxygen is a product of photosynthesis, not a raw material taken in — it is carbon dioxide, not oxygen, that plants take in as a raw material.',
 'Nitrogen is not a raw material for photosynthesis — the raw materials are carbon dioxide and water, using light energy captured by chlorophyll.',
 'Photosynthesis is the process by which plants use light energy to convert carbon dioxide and water into glucose, releasing oxygen as a by-product: 6CO2 + 6H2O -> C6H12O6 + 6O2. This reaction takes place mainly in the chloroplasts of leaf cells, which contain the pigment chlorophyll to absorb light energy.',
 'Photosynthesis: CO2 + water -> glucose + oxygen (using light energy) [1]',
 'ai_drafted', true, true),

('Biology','AQA','GCSE','Higher','Bioenergetics','Limiting Factors','TO_BE_VERIFIED',3,
 'A plant''s rate of photosynthesis is being measured as light intensity increases. Initially the rate increases, but eventually it levels off even as light intensity keeps increasing. What does this levelling off suggest?',
 'The plant has stopped photosynthesising entirely','Light intensity is no longer the limiting factor; some other factor, such as carbon dioxide concentration or temperature, is now limiting the rate','The plant has run out of chlorophyll permanently','Photosynthesis rate always levels off regardless of any other conditions','Not sure','b',
 'A levelling-off rate means photosynthesis is continuing at a steady rate, not that it has stopped entirely.',
 'Correct — once increasing light intensity no longer increases the rate of photosynthesis, some other factor (commonly carbon dioxide concentration or temperature) must now be limiting the rate instead — this is called a limiting factor.',
 'Levelling off does not indicate a permanent loss of chlorophyll — it indicates that a different factor besides light has become the constraint on the reaction rate.',
 'The specific factor causing the plateau (light, CO2, or temperature) depends on the actual growing conditions — it is not simply an automatic, unconditional levelling-off regardless of the environment.',
 'When one factor (such as light intensity) is increased and the rate of photosynthesis stops increasing and levels off, it means that factor is no longer limiting — some other factor, most commonly carbon dioxide concentration or temperature, has now become the limiting factor holding the rate steady, regardless of how much further light intensity increases.',
 'Levelling off indicates a different factor (e.g. CO2 or temperature) is now limiting [1]',
 'ai_drafted', true, true),

('Biology','AQA','GCSE','Higher','Bioenergetics','Aerobic Respiration','TO_BE_VERIFIED',2,
 'What is the word equation for aerobic respiration?',
 'Glucose + oxygen -> carbon dioxide + water','Carbon dioxide + water -> glucose + oxygen','Glucose -> lactic acid','Glucose -> ethanol + carbon dioxide','Not sure','a',
 'Correct — aerobic respiration is the process by which cells release energy from glucose using oxygen, producing carbon dioxide and water as waste products: glucose + oxygen -> carbon dioxide + water.',
 'This is the word equation for photosynthesis, not aerobic respiration — the reactants and products are the reverse of respiration.',
 'This describes anaerobic respiration in animal cells (producing lactic acid), not aerobic respiration, which uses oxygen and produces carbon dioxide and water.',
 'This describes anaerobic respiration in yeast/plant cells (producing ethanol and carbon dioxide), not aerobic respiration.',
 'Aerobic respiration is the process that releases energy from glucose using oxygen, and takes place continuously in living cells, mostly in the mitochondria. The word equation is: glucose + oxygen -> carbon dioxide + water. This is the most efficient way cells release energy for processes such as movement, growth, and keeping warm.',
 'Aerobic respiration: glucose + oxygen -> carbon dioxide + water [1]',
 'ai_drafted', true, true),

('Biology','AQA','GCSE','Higher','Bioenergetics','Anaerobic Respiration','TO_BE_VERIFIED',3,
 'During intense exercise, muscle cells may not receive oxygen fast enough to meet their energy demands, so they respire anaerobically. What substance builds up in the muscles as a result, and what effect does this have?',
 'Ethanol builds up, causing the muscles to relax completely','Lactic acid builds up, which can cause muscle fatigue and cramp','Glucose builds up, providing extra energy with no downside','Oxygen builds up, improving muscle performance further','Not sure','b',
 'Ethanol is produced by anaerobic respiration in yeast and some plant cells, not in human muscle cells, which produce lactic acid instead.',
 'Correct — in human muscle cells, anaerobic respiration produces lactic acid as a by-product. As lactic acid builds up, it can cause muscle fatigue and cramp, and it also creates an "oxygen debt" that must be repaid afterwards through continued heavy breathing.',
 'Anaerobic respiration releases much less energy per glucose molecule than aerobic respiration, and the lactic acid produced causes fatigue — it does not simply provide "extra energy with no downside."',
 'Oxygen does not build up during anaerobic respiration — the whole reason cells respire anaerobically is because there is not enough oxygen available to meet demand.',
 'When muscle cells cannot get enough oxygen during intense exercise, they respire anaerobically, releasing energy from glucose without using oxygen. This produces lactic acid as a by-product (rather than carbon dioxide and water). Lactic acid builds up in the muscles, contributing to muscle fatigue and cramp, and creates an "oxygen debt" that the body repays afterwards by continuing to breathe heavily to break down the lactic acid.',
 'Anaerobic respiration in muscles produces lactic acid, causing fatigue [1]',
 'ai_drafted', true, true),

-- Topic: Homeostasis and Response
('Biology','AQA','GCSE','Higher','Homeostasis and Response','The Nervous System','TO_BE_VERIFIED',2,
 'What is the general pathway that information follows in a simple nervous system response, from detecting a stimulus to producing a response?',
 'Effector -> receptor -> coordinator -> stimulus','Stimulus -> receptor -> coordinator (CNS) -> effector -> response','Response -> stimulus -> receptor -> effector','Stimulus -> effector -> receptor -> coordinator','Not sure','b',
 'This lists the pathway components in reverse order, starting from the effector rather than ending with it.',
 'Correct — a stimulus is detected by a receptor, which sends information (via a sensory neurone) to a coordinator (part of the central nervous system, i.e. the brain or spinal cord), which sends instructions (via a motor neurone) to an effector (a muscle or gland), which brings about the response.',
 'This starts with "response," which should come at the end of the pathway, after the effector has acted, not at the beginning.',
 'This has the effector and receptor in the wrong order — the receptor detects the stimulus first, before any signal reaches the coordinator or effector.',
 'The general pathway in a nervous system response is: stimulus -> receptor (detects the stimulus) -> coordinator, part of the central nervous system, i.e. brain or spinal cord (processes the information and decides on a response) -> effector, a muscle or gland (carries out the response) -> response.',
 'Pathway: stimulus -> receptor -> coordinator (CNS) -> effector -> response [1]',
 'ai_drafted', true, true),

('Biology','AQA','GCSE','Higher','Homeostasis and Response','Blood Glucose Control','TO_BE_VERIFIED',3,
 'After eating a meal, blood glucose concentration rises. How does the body respond to bring it back down to normal?',
 'The pancreas releases glucagon, which converts glycogen into glucose','The pancreas releases insulin, which causes cells (especially in the liver) to take up glucose from the blood and store it as glycogen','The kidneys filter out all the glucose and remove it from the body permanently','The liver stops producing glycogen entirely','Not sure','b',
 'Glucagon has the opposite effect — it is released when blood glucose is too LOW, causing glycogen to be converted back into glucose, which would raise blood glucose further, not lower it.',
 'Correct — when blood glucose rises after eating, the pancreas releases the hormone insulin. Insulin causes cells, especially liver cells, to take up glucose from the blood and store it as glycogen, lowering blood glucose concentration back towards normal.',
 'The kidneys are not the primary organs responsible for regulating blood glucose concentration under normal conditions — that role belongs to the pancreas, liver, and hormones insulin and glucagon.',
 'It is not that glycogen production stops — insulin actually promotes the conversion of excess glucose into glycogen for storage, which is the opposite of stopping glycogen production.',
 'Blood glucose concentration is controlled by hormones from the pancreas. When blood glucose rises (such as after eating), the pancreas releases insulin, which causes cells throughout the body, particularly in the liver, to take up glucose from the blood and convert it into glycogen for storage, bringing blood glucose back down towards its normal level.',
 'Insulin causes glucose uptake and storage as glycogen, lowering blood glucose [1]',
 'ai_drafted', true, true),

('Biology','AQA','GCSE','Higher','Homeostasis and Response','The Menstrual Cycle','TO_BE_VERIFIED',3,
 'Which hormone, released in the middle of the menstrual cycle, triggers ovulation (the release of an egg from the ovary)?',
 'Progesterone','Follicle-stimulating hormone (FSH), released continuously throughout the cycle','A surge of luteinising hormone (LH)','Oestrogen, at consistently low levels throughout the cycle','Not sure','c',
 'Progesterone maintains the uterus lining after ovulation, but it is not the hormone that directly triggers ovulation itself.',
 'FSH stimulates the maturation of an egg in the ovary earlier in the cycle, but it is a surge in a different hormone, LH, that actually triggers the release of the egg.',
 'Correct — a surge in luteinising hormone (LH) around the middle of the menstrual cycle triggers ovulation, causing the mature egg to be released from the ovary.',
 'Oestrogen levels rise (not stay consistently low) in the lead-up to ovulation, and this rise helps trigger the LH surge that then causes ovulation.',
 'The menstrual cycle is controlled by several hormones. FSH causes an egg to mature in the ovary and stimulates oestrogen release. Rising oestrogen levels trigger a surge in luteinising hormone (LH) around day 14 of a typical cycle, and this LH surge is what triggers ovulation — the release of the mature egg from the ovary.',
 'LH surge triggers ovulation [1]',
 'ai_drafted', true, true),

('Biology','AQA','GCSE','Higher','Homeostasis and Response','Reflex Arc','TO_BE_VERIFIED',2,
 'Why are reflex actions, such as pulling your hand away from something hot, faster than a considered, voluntary response?',
 'Reflex actions do not involve the nervous system at all','The pathway (reflex arc) bypasses conscious processing in the brain, going directly from sensory neurone to relay neurone to motor neurone, often via the spinal cord','Reflex actions only occur in the eyes, which naturally respond faster than other body parts','Reflex actions always involve more neurones than voluntary responses, making them faster','Not sure','b',
 'Reflex actions do involve the nervous system — they use a specific, rapid pathway of neurones, just without requiring conscious thought.',
 'Correct — in a reflex arc, the signal passes from a sensory neurone to a relay neurone, then to a motor neurone, often via the spinal cord, without needing to travel to the brain for conscious decision-making. This shorter pathway means the response happens much faster than a considered, voluntary action.',
 'Reflex actions are not limited to the eyes — many reflexes involve other parts of the body, such as the hand-withdrawal reflex from a hot object.',
 'Reflex arcs typically involve fewer neurones and a shorter pathway than voluntary responses (which involve conscious processing in the brain), and it is this shorter pathway, not a larger number of neurones, that makes them faster.',
 'A reflex action follows a reflex arc: a stimulus is detected by a receptor, and the signal passes along a sensory neurone to a relay neurone (often in the spinal cord), then directly to a motor neurone, which causes an effector (a muscle) to respond. Because this pathway bypasses the need for conscious processing in the brain, reflex responses happen much faster than voluntary, considered responses.',
 'Reflex arc bypasses conscious brain processing, making it faster [1]',
 'ai_drafted', true, true),

-- Topic: Inheritance, Variation and Evolution
('Biology','AQA','GCSE','Higher','Inheritance, Variation and Evolution','DNA Structure','TO_BE_VERIFIED',2,
 'What shape does a molecule of DNA form, and where in the cell is most of it found?',
 'A single straight strand, found in the cytoplasm','A double helix, found mainly in the nucleus of the cell','A flat sheet, found in the mitochondria only','A branching tree shape, found in the cell membrane','Not sure','b',
 'DNA is not a single straight strand — it is a double helix, made of two strands wound around each other, and it is not found mainly in the cytoplasm.',
 'Correct — DNA is a polymer made of two strands coiled together to form a double helix. In eukaryotic cells (such as human cells), most DNA is found in the nucleus, organised into structures called chromosomes.',
 'DNA does not form a flat sheet shape, and while mitochondria do contain a small amount of their own DNA, most of a cell''s DNA is found in the nucleus, not exclusively in the mitochondria.',
 'DNA does not form a branching tree shape, and it is not found in the cell membrane — it is located mainly in the nucleus.',
 'DNA (deoxyribonucleic acid) is a polymer made of two strands that coil around each other to form a double helix. In a eukaryotic cell such as a human cell, most of the cell''s DNA is found in the nucleus, tightly coiled into structures called chromosomes.',
 'DNA forms a double helix, found mainly in the nucleus [1]',
 'ai_drafted', true, true),

('Biology','AQA','GCSE','Higher','Inheritance, Variation and Evolution','Monohybrid Crosses','TO_BE_VERIFIED',3,
 'In pea plants, the allele for tall stems (T) is dominant over the allele for short stems (t). If two heterozygous tall plants (Tt) are crossed, what proportion of their offspring would be expected to be short?',
 '0% (none)','25% (1 in 4)','50% (1 in 2)','100% (all of them)','Not sure','b',
 'Some offspring are expected to be short — heterozygous parents (Tt x Tt) can produce homozygous recessive (tt, short) offspring, so it is not zero.',
 'Correct — crossing Tt x Tt gives a genotype ratio of 1 TT : 2 Tt : 1 tt across the offspring (shown clearly on a Punnett square). Only the tt genotype produces the short phenotype, since t is recessive, so 1 in 4 (25%) of offspring are expected to be short.',
 'Half the offspring being short would only occur in different specific crosses (such as Tt x tt), not in a Tt x Tt cross, which gives 25% short offspring.',
 'Not all offspring will be short — three-quarters of the offspring (TT and Tt genotypes) will show the dominant tall phenotype; only the tt genotype (1 in 4) will be short.',
 'A Punnett square for Tt x Tt gives the genotype combinations TT, Tt, Tt, and tt among the four possible offspring combinations — a ratio of 1 TT : 2 Tt : 1 tt. Since T (tall) is dominant, both TT and Tt genotypes show the tall phenotype (3 out of 4, or 75%). Only the tt genotype shows the recessive short phenotype, which is 1 out of 4, or 25%, of the offspring.',
 'Tt x Tt gives 1:2:1 genotype ratio; 25% are tt (short phenotype) [1]',
 'ai_drafted', true, true),

('Biology','AQA','GCSE','Higher','Inheritance, Variation and Evolution','Natural Selection','TO_BE_VERIFIED',3,
 'A population of insects shows variation in colour. A change in the environment makes darker insects harder for predators to spot. Over many generations, how would you expect this to affect the population, and why?',
 'The proportion of darker insects would increase, because they are more likely to survive and reproduce, passing on the alleles for dark colour','The population would become entirely uniform in a single generation, with no variation at all','Insects would consciously change their own colour to survive better','The proportion of lighter insects would increase, since predators focus more on darker prey','Not sure','a',
 'Correct — this is natural selection in action: darker insects are less likely to be eaten, so are more likely to survive and reproduce, passing on the alleles for dark colouring to their offspring. Over many generations, the proportion of the population with the advantageous darker colouring is expected to increase.',
 'Natural selection acts gradually over many generations, not by producing complete uniformity within a single generation — some variation typically persists.',
 'Organisms cannot consciously choose to change their own genetically-determined traits — natural selection works because individuals with an advantageous inherited variation survive and reproduce more successfully, not through deliberate change.',
 'This has the selection pressure backwards — since predators find it harder to spot darker insects (not lighter ones), it is the darker insects that would be expected to survive better and increase in proportion, not the lighter ones.',
 'This scenario describes natural selection: within the population, there is already variation in colour. Because darker insects are harder for predators to spot, they are more likely to survive long enough to reproduce, passing their alleles for dark colouring on to their offspring. Over many generations, since more of the surviving, reproducing insects are dark, the proportion of the population with dark colouring is expected to increase.',
 'Advantageous trait (dark colour) increases in frequency via natural selection over generations [1]',
 'ai_drafted', true, true),

('Biology','AQA','GCSE','Higher','Inheritance, Variation and Evolution','Evolution','TO_BE_VERIFIED',2,
 'What is meant by "evolution" in a biological sense?',
 'A sudden change that occurs within a single organism''s lifetime','The gradual change in the inherited characteristics of a population over many generations','The process by which an individual organism learns new skills','A change in an organism''s environment, unrelated to its genes','Not sure','b',
 'Evolution does not describe a change within a single organism''s own lifetime — an individual organism''s genes do not change through evolution; it is populations, over generations, that evolve.',
 'Correct — evolution is the gradual change in the inherited characteristics of a population over many generations, arising through processes such as natural selection acting on genetic variation within the population.',
 'Evolution is not about an individual learning new skills during its lifetime — those skills are not passed on genetically, and learning is a different process entirely from evolutionary, inherited change.',
 'Evolution specifically concerns changes in a population''s inherited (genetic) characteristics, not simply environmental change on its own — though environmental change can act as a selection pressure driving evolution.',
 'Evolution is the gradual change in the inherited characteristics of a population of organisms over many generations. It occurs through processes such as natural selection, where individuals with characteristics better suited to their environment are more likely to survive and reproduce, passing those advantageous inherited characteristics on to future generations.',
 'Evolution = gradual change in inherited characteristics of a population over generations [1]',
 'ai_drafted', true, true),

-- Topic: Ecology
('Biology','AQA','GCSE','Higher','Ecology','Food Chains','TO_BE_VERIFIED',1,
 'In the food chain "grass -> rabbit -> fox," what role does the rabbit play?',
 'Producer','Primary consumer','Secondary consumer','Decomposer','Not sure','b',
 'A producer is an organism, typically a plant, that makes its own food by photosynthesis — the grass is the producer in this food chain, not the rabbit.',
 'Correct — the rabbit eats the grass (a producer) directly, making it a primary consumer. Primary consumers are always the organisms that feed directly on producers.',
 'A secondary consumer eats a primary consumer — that role belongs to the fox in this food chain, which eats the rabbit, not to the rabbit itself.',
 'A decomposer breaks down dead organic matter — the rabbit is a living consumer in this food chain, not a decomposer.',
 'In a food chain, the producer (usually a green plant, here grass) makes its own food by photosynthesis. The primary consumer is the organism that eats the producer directly — here, the rabbit, which eats grass. The secondary consumer eats the primary consumer — here, the fox, which eats the rabbit.',
 'Rabbit is the primary consumer, eating the producer (grass) [1]',
 'ai_drafted', true, true),

('Biology','AQA','GCSE','Higher','Ecology','The Carbon Cycle','TO_BE_VERIFIED',2,
 'Which process removes carbon dioxide from the atmosphere and is carried out by plants?',
 'Respiration','Combustion','Photosynthesis','Decomposition','Not sure','c',
 'Respiration releases carbon dioxide into the atmosphere (as a waste product of releasing energy from glucose), rather than removing it.',
 'Combustion (burning) releases carbon dioxide into the atmosphere, particularly from burning fossil fuels — it does not remove carbon dioxide.',
 'Correct — photosynthesis removes carbon dioxide from the atmosphere, using it (along with water and light energy) to produce glucose, which becomes part of the plant''s biomass.',
 'Decomposition releases carbon dioxide back into the atmosphere as decomposers break down dead organic matter and respire — it does not remove carbon dioxide.',
 'In the carbon cycle, photosynthesis is the main process that removes carbon dioxide from the atmosphere: plants use carbon dioxide, water, and light energy to produce glucose, incorporating carbon into their biomass. Processes such as respiration, combustion, and decomposition all return carbon dioxide to the atmosphere.',
 'Photosynthesis removes CO2 from the atmosphere [1]',
 'ai_drafted', true, true),

('Biology','AQA','GCSE','Higher','Ecology','Biodiversity','TO_BE_VERIFIED',2,
 'What does "biodiversity" mean, and why is maintaining a high level of it generally considered important?',
 'Biodiversity is the total number of individual organisms in one specific species; high biodiversity means one species has a very large population','Biodiversity is the variety of different species living in an area; high biodiversity helps maintain stable, resilient ecosystems','Biodiversity refers only to plant species, ignoring animals, fungi, and microorganisms','Biodiversity always decreases naturally over time and cannot be maintained by human action','Not sure','b',
 'Biodiversity is about the variety of different species present, not simply the population size of one particular species.',
 'Correct — biodiversity is the variety of different species living in an ecosystem or area. High biodiversity generally supports greater ecosystem stability and resilience, since ecosystems with more species tend to be better able to withstand environmental changes or the loss of any single species.',
 'Biodiversity considers the full range of living organisms in an area, including animals, fungi, and microorganisms, not plants alone.',
 'Biodiversity is significantly affected by human activity (both positively and negatively) — conservation efforts, protected areas, and reduced habitat destruction can help maintain or increase biodiversity, so it is not simply an inevitable, uncontrollable decline.',
 'Biodiversity is the variety of different species of organisms living within an ecosystem or a given area. Maintaining high biodiversity is generally considered important because ecosystems with a greater variety of species tend to be more stable and resilient — better able to cope with environmental changes, disease, or the loss of any one species, since other species can often fill similar ecological roles.',
 'Biodiversity = variety of species; supports ecosystem stability and resilience [1]',
 'ai_drafted', true, true),

('Biology','AQA','GCSE','Higher','Ecology','Abiotic and Biotic Factors','TO_BE_VERIFIED',2,
 'A population of fish in a lake declines sharply after a factory begins discharging warm water into the lake, raising its temperature. Is this an example of an abiotic or a biotic factor affecting the population, and why?',
 'Biotic, because it involves a living organism (the fish)','Abiotic, because temperature is a non-living, physical/chemical factor affecting the organisms in the ecosystem','Neither — factory activity cannot be classified as either type of factor','Biotic, because factories are considered living systems in ecology','Not sure','b',
 'The fish being a living organism does not make the CAUSE of the change biotic — it is the temperature change itself, a non-living physical factor, that is being classified here.',
 'Correct — abiotic factors are non-living, physical or chemical factors that affect organisms in an ecosystem, such as temperature, light intensity, pH, and moisture level. A rise in water temperature is a classic example of an abiotic factor.',
 'Environmental changes caused by human activity, such as a factory discharging warm water, can and do affect abiotic factors (like temperature) within ecosystems — this is a well-established, classifiable ecological factor.',
 'A factory is not a living organism and is not considered a "biotic" factor in ecology — biotic factors specifically refer to living organisms (such as predators, competitors, or pathogens) within an ecosystem.',
 'Ecological factors affecting organisms are classified as either biotic (living factors, such as predation, competition, and disease) or abiotic (non-living, physical or chemical factors, such as temperature, light intensity, and pH). A rise in water temperature — even though it is caused by human/factory activity — is an abiotic factor, since temperature itself is a non-living, physical property of the environment.',
 'Temperature is an abiotic (non-living) factor [1]',
 'ai_drafted', true, true);
